function dashboardPage() {
  const p = state.profile;
  const copy = text.routes.dashboard;
  return shell(`
    ${pageHeader("dashboard")}
    <section class="dashboard">
      <div class="profile-visual" style="box-shadow:0 0 0 3px ${typeColorFromCode(p.code)};position:relative;">
        ${getUserPhoto()
          ? `<img id="user-photo-img" src="${getUserPhoto()}" alt="My photo" style="position:absolute;inset:0;width:100%;height:100%;margin:0;object-fit:cover;border-radius:inherit;" />`
          : (p.image ? `<img src="${p.image}" alt="${text.meta.resonanceImageAltPrefix} ${p.code}" style="position:absolute;top:${tierAvatarTop(p.code)};left:${tierAvatarLeft(p.code)};width:140%;height:140%;margin:0;object-fit:cover;" />` : `<div class="profile-badge profile-badge--large">${p.emoji || enCode(p.code)}</div>`)
        }
      </div>
      <div style="display:flex;flex-direction:column;align-items:center;margin-top:0.5rem;gap:0.4rem;">
        <button id="user-photo-menu-btn" style="background:var(--surface);border:1px solid var(--border);color:var(--muted);border-radius:20px;padding:0.3rem 0.9rem;font-size:0.78rem;cursor:pointer;display:inline-flex;align-items:center;gap:0.3rem;">
          📷 ${getUserPhoto() ? 'Photo ▾' : 'Add photo'}
        </button>
        <input type="file" accept="image/*" id="user-photo-input" style="display:none;" />
        <div id="user-photo-menu" style="display:none;flex-direction:column;background:var(--surface);border:1px solid var(--border);border-radius:12px;overflow:hidden;width:180px;">
          <label id="user-photo-btn" style="display:block;padding:0.55rem 1rem;font-size:0.82rem;cursor:pointer;color:var(--text);text-align:center;">📷 Change photo
            <input type="file" accept="image/*" id="user-photo-input2" style="display:none;" />
          </label>
          ${getUserPhoto() ? `<button id="user-photo-del" style="display:block;width:100%;text-align:center;padding:0.55rem 1rem;font-size:0.82rem;cursor:pointer;background:none;border:none;border-top:1px solid var(--border);color:#c0392b;">✕ Remove photo</button>` : ''}
        </div>
      </div>
      <div class="dashboard__copy">
        <p class="eyebrow">${copy.greeting} · ${CENTER_EN[p.center] || p.center} · ${TYPELABEL_EN[p.typeLabel] || p.typeLabel || ''}</p>
        <h1>${enCode(p.code)} · ${p.title_en || p.title}</h1>
        <p class="subtle-archetype">${p.titleAlt ? `also: ${TITLEALT_EN[p.titleAlt] || p.titleAlt} · ` : ''}${copy.animalBackground} ${p.archetype_en || p.archetype}</p>
        ${p.variant ? `<span class="variant-tag variant-tag--${p.variant.toLowerCase().replace('ä','ae').replace('ü','ue')}">${VARIANT_EN[p.variant] || p.variant}</span>` : ''}
        <p class="focus">Your Focus as ${enCode(p.code)}: ${p.focus_en || p.focus}</p>
        <div class="question-box">
          <span>${copy.organismQuestion}</span>
          <p>${ORGANISM_Q_EN[p.organismQuestion] || p.organismQuestion}</p>
        </div>
        <button class="ghost-link" data-route="profile">Switch profile →</button>
        <button class="ghost-link" data-route="typalbum" style="margin-top:0.3rem;font-size:0.82rem;">🗂 My Type Album →</button>
        <a href="./vorstellung.html#video" target="_blank" rel="noopener" class="ghost-link" style="margin-top:0.3rem;font-size:0.82rem;text-decoration:none;display:inline-block;">🎬 Watch the intro video →</a>
        <button id="push-enable-btn" class="ghost-link" style="margin-top:0.3rem;font-size:0.78rem;color:var(--muted);">🔔 Enable push notifications</button>
        <button class="ghost-link voice-mute-btn-inline" onclick="toggleVoiceMute()" style="margin-top:0.3rem;font-size:0.78rem;color:${isVoiceMuted() ? "var(--muted)" : "var(--gold)"};">${isVoiceMuted() ? "🔇 Greeting voice off – tap to enable" : "🔊 Greeting voice on – tap to disable"}</button>
      </div>
    </section>
    <section class="daily-grid">
      ${(()=>{const _imp=dailyPick(p.daily.impulse);return infoCard(copy.dailyImpulse,`<span id="daily-impulse-en" data-de="${_imp.replace(/"/g,'&quot;')}">${_imp}</span>`);})()}
      ${infoCard(copy.reflectionQuestion, (DAILY_QUESTION_EN[p.daily.question] || p.daily.question))}
      ${infoCard(copy.nextStep, (DAILY_STEP_EN[p.daily.step] || p.daily.step))}
    </section>
    <section class="quick-actions">
      <button class="primary" data-route="reflection">${copy.reflectToday}</button>
      <button class="secondary" data-route="path">${copy.viewPath}</button>
      <button class="secondary" data-route="tools">${copy.chooseTool}</button>
      <button class="secondary" data-route="knowledge">${copy.checkKnowledge}</button>
    </section>
    <section class="narrow" style="margin-top:2.5rem;">
      <blockquote class="kompass-zitat">
        <p>&ldquo;We do not see the world as it (objectively) is, but as we (subjectively) perceive it &ndash; according to our Enneagram type.&rdquo;</p>
        <p style="margin-top:0.75rem;">This is the source of all problems between people, but also potentially all solutions to these interpersonal problems — and ultimately all problems and solutions in this world.</p>
        <footer>— Detlef Rathmer, 2026</footer>
      </blockquote>
    </section>
  `);
}

function reflectionPage() {
  const p = state.profile;
  const copy = text.routes.reflection;
  const saved = getJournal();
  return shell(`
    ${pageHeader("reflection")}
    <section class="narrow">
      <p class="eyebrow">${p.code} · ${copy.suffix}</p>
      <h1>${copy.headline}</h1>
      <label class="journal">
        <span>${DAILY_QUESTION_EN[p.daily.question] || p.daily.question}</span>
        <textarea id="journalText" rows="9" placeholder="${copy.placeholder}">${saved}</textarea>
      </label>
      <div class="form-row">
        <button class="primary" id="saveJournal">${copy.save}</button>
        <span id="saveStatus" role="status"></span>
      </div>
      <div class="soft-note">
        <strong>${copy.smallStep}</strong>
        <p>${DAILY_STEP_EN[p.daily.step] || p.daily.step}</p>
      </div>
    </section>
  `);
}

function pathPage() {
  const p = state.profile;
  const copy = text.routes.path;
  return shell(`
    ${pageHeader("path")}
    <section class="narrow centered">
      <p class="eyebrow">${p.code} · ${copy.suffix}</p>
      <h1>${copy.headline}</h1>
      <p class="lead-small">${p.coreSentence_en || p.coreSentence}</p>
    </section>
    <section class="path-grid">
      ${listPanel(copy.pattern, p.pattern, "pattern")}
      <div class="bridge">${compassMark("small")}<span>${copy.bridge}</span></div>
      ${listPanel(copy.growth, p.growth, "growth")}
    </section>
  `);
}

