function affiliateBoxHtml(category, remedyName, label) {
  return `
    <a href="${AFFILIATE_LINKS[category][remedyName]}" target="_blank" rel="noopener sponsored" class="remedy-card__affiliate">
      <img src="../assets/detlef-rathmer-empfehlung.jpg" alt="Detlef Rathmer" class="remedy-card__affiliate-photo" loading="lazy" />
      <span class="remedy-card__affiliate-text">
        <span class="remedy-card__affiliate-label">${label || "See my recommendation on Amazon"}</span>
        <span class="remedy-card__affiliate-note">Advertising Link · Amazon Associates Program</span>
      </span>
    </a>`;
}

const MEDITATIONS_SITZHILFEN = [
  { name: "Meditation Mat", subtitle: "Zabuton", eignung: "The foundation for everyone: it lies flat on the floor and cushions the knees and ankles — whether or not a cushion or bench is placed on top. Best suited for beginners and anyone sitting on a hard floor (parquet, tile)." },
  { name: "Meditation Cushion", subtitle: "Zafu", eignung: "Best for those who like to sit cross-legged or in a lotus position: it lifts the hips above the knees, allowing an upright, relaxed back. Well suited if your hips are already reasonably flexible." },
  { name: "Singing Bowl", subtitle: "Therapy-Grade Sound Bowl", eignung: "Best for those who want to deepen their stillness practice through sound: the tone of a genuine therapy-grade singing bowl calms the nervous system and marks the beginning and end of the practice. Especially well suited for anyone working with body work, sound massage, or subtle-energy practices." },
  { name: "Meditation Bench", subtitle: "Seiza", eignung: "Best for those who find cross-legged sitting uncomfortable or who have knee, hip or back issues: sitting kneeling on the bench takes pressure off the knees while the back stays upright with ease — comfortable even for beginners." },
];

function heilmittelSection(h, oel, code) {
  const w = text.knowledgeCard.heilmittel;
  const enName = (v) => GERMAN_REMEDY_NAMES_EN[v] || v;
  const enDesc = (v) => REMEDY_GLOSSARY_EN[v] || null;
  const row = (label, value, category) => {
    const displayValue = enName(value || "");
    const meaning = displayValue && enDesc(value) ? `<small class="remedy-row__meaning">${enDesc(value)}</small>` : "";
    const affiliate = value && category && AFFILIATE_LINKS[category]?.[value] ? affiliateBoxHtml(category, value) : "";
    return `<li class="remedy-row"><span class="remedy-row__label">${label}</span><span class="remedy-row__value${displayValue ? "" : " remedy-row__value--empty"}">${displayValue || w.pending}${meaning}${affiliate}</span></li>`;
  };
  const passion = h.leidenschaft || {};
  const wound = h.wunde || {};
  const seite4 = code ? `${CDN}assets/knowledge/type-${code.slice(-1)}/${code.toLowerCase()}/${code.toLowerCase()}-page-4.jpeg` : null;
  const typeKey = code ? PAGE4_TYPE_MAP[(code).toLowerCase()] : null;
  const enData = typeKey ? PAGE4_SUMMARY_EN[typeKey] : null;
  const passionTheme = enData ? `${enData.passion.theme} ${enData.passion.effect}` : (h.homoeopathieThema ? `${h.homoeopathieThema} ${h.homoeopathieWirkung || ""}` : "");
  const woundTheme = enData ? `${enData.wound.theme} ${enData.wound.effect}` : (h.wundeThema ? `${h.wundeThema} ${h.wundeWirkung || ""}` : "");
  const typeNum = code ? parseInt(String(code).replace(/\D/g, ""), 10) : null;
  const oilEN = typeNum && OILS_EN[typeNum] ? OILS_EN[typeNum] : null;
  return `
    <div class="knowledge-section heilmittel-box" id="heilmittel-kompass">
      <strong>${w.title}</strong>
      ${seite4 ? `
      <figure class="vollseite-karte">
        <p class="vollseite-karte__hint">Tap to enlarge</p>
        <img src="${seite4}" alt="Remedies Compass Overview" class="vollseite-karte__img" loading="lazy"
          onerror="this.closest('.vollseite-karte').style.display='none'" />
        <figcaption class="vollseite-karte__titel">Page 4 · Remedies Compass</figcaption>
      </figure>` : ""}
      ${page4SummaryBlock(code)}
      <div class="remedy-level">
        <span class="remedy-level__title remedy-level__title--passion">${w.leidenschaftTitle}</span>
        <ul class="remedy-list">
          ${row(w.homoeopathie, passion.homoeopathie, "homoeopathie")}
          ${row(w.schuessler, passion.schuessler, "schuessler")}
          ${row(w.bachbluete, passion.bachbluete, "bachbluete")}
          ${row(w.edelstein, passion.edelstein, "edelstein")}
          ${row(w.tee, passion.tee, "tee")}
        </ul>
        ${passionTheme ? `<p class="remedy-theme"><strong>${enName(passion.homoeopathie) || w.homoeopathie}:</strong> ${passionTheme}</p>` : ""}
      </div>
      <div class="remedy-level">
        <span class="remedy-level__title remedy-level__title--wound">${w.wundeTitle}</span>
        <ul class="remedy-list">
          ${row(w.homoeopathie, wound.homoeopathie, "homoeopathie")}
          ${row(w.schuessler, wound.schuessler, "schuessler")}
          ${row(w.bachbluete, wound.bachbluete, "bachbluete")}
        </ul>
        ${woundTheme ? `<p class="remedy-theme"><strong>${enName(wound.homoeopathie) || w.homoeopathie}:</strong> ${woundTheme}</p>` : ""}
        ${
          oilEN
            ? `<div class="remedy-oil">
                 <div class="remedy-oil__image"><img src="${oilEN.image}" alt="${oilEN.name}" loading="lazy" /></div>
                 <div class="remedy-oil__body">
                   <span class="remedy-oil__label">${w.aetherischesOel}</span>
                   <strong>${oilEN.name}</strong>
                   <p>${oilEN.wirkung}</p>
                   ${oilEN.vertiefung ? `<p class="remedy-oil__vertiefung" style="margin-top:.5rem;font-size:.88rem;line-height:1.65;">${oilEN.vertiefung}</p>` : ""}
                   ${AFFILIATE_LINKS.oel[oilEN.name] ? affiliateBoxHtml("oel", oilEN.name) : ""}
                 </div>
               </div>`
            : ""
        }
      </div>
      <p class="remedy-note">${w.note}</p>
      <p class="remedy-note remedy-note--individual">${w.individualNote}</p>
    </div>
  `;
}



function page1SummaryBlock(code) {
  if (!code) return "";
  const d = PAGE1_SUMMARY_EN[(code).toLowerCase()];
  if (!d) return "";
  const ul = (arr) => arr && arr.length ? `<ul>${arr.map(i => `<li>${i}</li>`).join("")}</ul>` : "";
  return `
    <div class="page1-summary">
      <h4 class="page1-summary__theme">${d.coreTheme}</h4>
      <p class="page1-summary__identities">${d.identities}</p>
      <p class="page1-summary__statement"><em>"${d.coreStatement}"</em></p>
      <div class="room-field"><strong>Organism Question</strong><p><em>${d.organismQuestion}</em></p></div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Gaze Quality</strong>${ul(d.gazeQuality)}</div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Micro-Tension</strong>${ul(d.microTension)}</div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Breathing Rhythm</strong>${ul(d.breathingRhythm)}</div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Movement Initiation</strong>${ul(d.movementInitiation)}</div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Contact Style</strong>${ul(d.contactStyle)}</div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Tension Distribution</strong><p>${d.tensionDistribution}</p></div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Embodied Signature</strong>${ul(d.embodiedSignature)}</div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Core Tension</strong><p>${d.coreTension}</p></div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Integration Path</strong><p>${d.integrationPath}</p></div>
      <div class="room-field" style="padding-top:.8rem;"><p style="margin:0 0 .3rem;font-weight:700;">Animal: ${d.animal.name}</p><p style="margin:0 0 .8rem;">${d.animal.description}</p></div>
      <div class="room-field" style="padding-top:.8rem;"><strong>Resource Field</strong>${ul(d.resourceField)}</div>
      <div class="room-field page1-summary__footer"><span>${d.energeticTemp}</span> &nbsp;·&nbsp; <span>${d.attention}</span> &nbsp;·&nbsp; <span>${d.lifeFocus}</span></div>
    </div>
  `;
}
function woundBehindPassionSection(wound, code) {
  const w = text.knowledgeCard.woundBehindPassion;
  const en = code ? (WOUNDS_EN[(code).toLowerCase()] || {}) : {};
  const steps = [
    ["passion", w.passion],
    ["belief", w.belief],
    ["wound", w.wound],
    ["compensation", w.compensation],
    ["sufferingCycle", w.sufferingCycle],
    ["healingDirection", w.healingDirection],
    ["remedy", w.remedy],
  ];
  const placeholder = `<span class="wound-step__pending">${w.pending}</span>`;
  return `
    <div class="knowledge-section wound-box">
      <strong>${w.title}</strong>
      <ol class="wound-chain">
        ${steps
          .map(
            ([key, label]) => `
          <li class="wound-step${(en[key] || wound[key]) ? "" : " wound-step--empty"}">
            <span class="wound-step__label">${label}</span>
            <span class="wound-step__value">${(en[key] || wound[key]) ? (en[key] || wound[key]) : placeholder}</span>
          </li>`,
          )
          .join("")}
      </ol>
    </div>
  `;
}

function remedyCardSection(cards) {
  const labels = text.knowledgeCard;
  return `
    <div class="knowledge-section remedy-card-section">
      <strong>${labels.remedyCards}</strong>
      <p class="remedy-card-section__note">${labels.remedyCardsNote}</p>
      <div class="remedy-card-grid">
        ${cards.map((card) => `
          <article class="remedy-card">
            <div class="remedy-card__image">
              <img src="${card.image}" alt="${card.title} · ${card.subtitle}" loading="lazy" />
            </div>
            <div class="remedy-card__body">
              <span>${card.category}</span>
              ${card.imageStatus ? `<span class="remedy-card__image-status">${card.imageStatus}</span>` : ""}
              <h3>${card.title}</h3>
              <em>${card.subtitle}</em>
              <p class="remedy-card__field">${card.field}</p>
              <p>${card.text}</p>
              <small>${card.goal}</small>
              ${card.imagePlan ? `<small class="remedy-card__plan">${card.imagePlan}</small>` : ""}
            </div>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

