function typentestMotivationalPage() {
  const ms = motivState;

  // ── Phase: Intro ───────────────────────────────────────────────────────────
  if (ms.phase === "intro") {
    return shell(`
      ${pageHeader("typentest-motivational")}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">Motivational Enneagram Type Test &middot; for Advanced Users</p>
          <h1 class="typentest-titel">Recognizing the Deeper Drive</h1>
          <p class="typentest-intro">This test asks about your motivations, not your behavior. For each of the 100 questions, choose the two statements that apply to you most.</p>
          <div class="typentest-hinweis" style="margin-bottom:1.2rem;">
            <strong>Important note before you start:</strong> Even this test – thorough as it is – cannot prove your type. You are evaluating yourself, and we are all often blind to our own psychological and inner aspects. A mistyping can do more harm than good: Whoever goes through the world with the wrong type interprets themselves and others through a distorted lens. So take the result as an initial orientation – not as final truth. Only when a type feels consistently right from within over a longer period of time can it be trusted.
          </div>
          <ul class="typentest-hinweis" style="list-style:none;padding:0;margin:1.2rem 0;">
            <li style="padding:0.35rem 0;border-bottom:1px solid var(--line);">&#8226; 100 questions from various areas of life</li>
            <li style="padding:0.35rem 0;border-bottom:1px solid var(--line);">&#8226; Per question: 1st choice (most important) + 2nd choice (second most important)</li>
            <li style="padding:0.35rem 0;border-bottom:1px solid var(--line);">&#8226; Duration: approx. 20&ndash;30 minutes</li>
            <li style="padding:0.35rem 0;">&#8226; Recommendation: quiet atmosphere, honest answers</li>
          </ul>
          ${bookTip("motivationaler-enneagramm-typentest", "The book accompanying the test &ndash; motivational backgrounds, evaluation aids, and in-depth explanations for all 9 types.", "Motivationaler Enneagrammtypentest")}
          <button class="typentest-start-btn" data-motiv-start>Start Test &#8594;</button>
        </div>
      </div>
    `);
  }

  // ── Phase: Test ────────────────────────────────────────────────────────────
  if (ms.phase === "test") {
    const total = MOTIVTEST.length;
    const qi = ms.qIndex;
    const q = MOTIVTEST[qi];
    const pct = Math.round((qi / total) * 100);
    const ans = ms.answers[q.nr] || {};
    const letters = Object.keys(q.antworten);

    const answerCards = letters.map(letter => {
      const isFirst = ans.first === letter;
      const isSecond = ans.second === letter;
      const cls = isFirst ? "motiv-answer motiv-answer--first"
                : isSecond ? "motiv-answer motiv-answer--second"
                : "motiv-answer";
      const badge = isFirst ? `<span class="motiv-answer__badge">1</span>`
                  : isSecond ? `<span class="motiv-answer__badge">2</span>`
                  : "";
      return `<button class="${cls}" data-motiv-answer="${letter}" data-motiv-qnr="${q.nr}">
        ${badge}
        <span class="motiv-answer__text">${q.antworten[letter]}</span>
      </button>`;
    }).join("");

    const hasTwo = ans.first && ans.second;
    const canNext = hasTwo;

    return shell(`
      ${pageHeader("typentest-motivational")}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <div class="motiv-progress">
            <span class="motiv-progress__label">Question ${qi + 1} of ${total}</span>
            <div class="motiv-progress__track"><div class="motiv-progress__bar" style="width:${pct}%"></div></div>
          </div>
          <p class="eyebrow" style="margin-top:1.2rem;">Question ${q.nr}: ${q.thema}</p>
          <p class="typentest-frage">${q.frage}</p>
          <p class="typentest-intro" style="margin-bottom:0.8rem;">Choose the <strong>two</strong> statements that apply to you most &ndash; first the most accurate, then the second most accurate.</p>
          <div class="motiv-answer-grid">
            ${answerCards}
          </div>
          <div class="typentest-cta-group" style="margin-top:1.5rem;">
            ${qi > 0 ? `<button class="ghost-link" data-motiv-back>&#8592; Back</button>` : ""}
            <button class="typentest-start-btn" data-motiv-next ${canNext ? "" : "disabled"} style="${canNext ? "" : "opacity:0.45;cursor:not-allowed;"}">${qi < total - 1 ? "Next &#8594;" : "Show Result &#8594;"}</button>
            <button class="ghost-link" data-motiv-skip style="font-size:0.8rem;opacity:0.6;">Skip Question</button>
          </div>
        </div>
      </div>
    `);
  }

  // ── Phase: Result ──────────────────────────────────────────────────────────
  if (ms.phase === "result") {
    playMilestone("test-abgeschlossen");
    const scores = {};
    for (let t = 1; t <= 9; t++) scores[t] = 0;
    for (const [, ans] of Object.entries(ms.answers)) {
      if (ans.first)  { const t = LETTER_TO_TYPE[ans.first];  if (t) scores[t] += 6; }
      if (ans.second) { const t = LETTER_TO_TYPE[ans.second]; if (t) scores[t] += 3; }
    }
    const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
    const topType = parseInt(sorted[0][0]);
    const topScore = sorted[0][1];
    const maxScore = topScore || 1;
    const top3 = sorted.slice(0, 3);

    const typColors = {
      1:"#7d593d",2:"#a5603d",3:"#30483d",4:"#5a4070",
      5:"#243948",6:"#607468",7:"#d4900a",8:"#8b2020",9:"#556b2f"
    };
    const typColor = typColors[topType] || "var(--copper)";

    const scoreBars = sorted.map(([typ, score], i) => {
      const pct = Math.round((score / maxScore) * 100);
      const highlight = i === 0 ? `style="background:${typColor}"` : "";
      return `
        <div class="motiv-score-row">
          <span class="motiv-score-label">Typ&nbsp;${typ}</span>
          <div class="motiv-score-track">
            <div class="motiv-score-bar ${i === 0 ? "motiv-score-bar--top" : ""}" ${highlight} style="width:${pct}%"></div>
          </div>
          <span class="motiv-score-num">${score}</span>
        </div>`;
    }).join("");

    return shell(`
      ${pageHeader("typentest-motivational")}
      <div class="typentest-wrap">
        <div class="typentest-card typentest-card--result">
          <p class="eyebrow">Your Result</p>
          <div class="typentest-result-badge" style="border-color:${typColor};color:${typColor}">${topType}</div>
          <h2 class="typentest-titel" style="color:${typColor}">${TYPNAMEN_MOTIV[topType]}</h2>
          <p class="typentest-intro">Your evaluation points to <strong>Type&nbsp;${topType}</strong>. The result is based on your self-assessment and should be understood as an orientation guide.</p>

          <div class="typentest-disclaimer" style="margin-top:1.5rem;">
            <strong>For context:</strong> No self-test can fully bridge one's own blind spot. The result is a <em>hint</em>, not a verdict. For a precise determination, a personal typing consultation is recommended.
          </div>

          <div class="typentest-cta-group">
            <button class="primary" style="background:${typColor};border-color:${typColor}" data-route="type/${topType}">Go to Type&nbsp;${topType} in the Compass &#8594;</button>
            <p class="typentest-berater-label">Request a consultation appointment:</p>
            <a class="typentest-cta-btn" href="mailto:detlefrathmer@t-online.de?subject=Request%20a%20Typing%20Consultation">&#9993; Request consultation with Detlef Rathmer</a>
            <a class="typentest-cta-btn typentest-cta-btn--wa" href="https://wa.me/4915758786201?text=I%20would%20like%20to%20request%20a%20typing%20consultation." target="_blank" rel="noopener">WhatsApp Detlef Rathmer</a>
            <a class="typentest-cta-btn" href="mailto:rathmer.david.business@gmail.com?subject=Request%20a%20Typing%20Consultation">&#9993; Request consultation with David L. Rathmer</a>
            <a class="typentest-cta-btn typentest-cta-btn--wa" href="https://wa.me/4915901902479?text=I%20would%20like%20to%20request%20a%20typing%20consultation." target="_blank" rel="noopener">WhatsApp David L. Rathmer</a>
          </div>

          <button class="ghost-link" data-motiv-reset>Retake Test</button>
          <button class="ghost-link" data-route="dashboard">&#8592; Go to Dashboard</button>
        </div>
      </div>
    `);
  }

  return shell(`${pageHeader("typentest-motivational")}<div class="typentest-wrap"><p>Error in test.</p></div>`);
}

function typentestPage() {
  if (!hasBasis()) { go("freischalt/basis"); return ""; }
  const ts = testState;
  const navBar = () => pageHeader("typentest");

  // Phase 0: Intro
  if (ts.phase === 0) {
    return shell(`
      ${navBar()}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">Structural Enneagram Type Test &middot; for Beginners</p>
          <h1 class="typentest-titel">Decode Your Personality</h1>
          <p class="typentest-intro">This test leads you in three steps to an initial indication of your Enneagram type and instinctual center. It takes about 7&ndash;10 minutes.</p>
          <div class="typentest-hinweis">
            <strong>Important note before you start:</strong> No test can truly prove your type – because you fill it out yourself, and we are all often blind to our own psychological and inner aspects. The result is therefore always only an <em>approximation</em>: it familiarizes you with the questions of the Enneagram and gives an initial point of orientation. The more extensive a test, the closer it comes to a possible type determination – but even this test does not replace personal guidance or a typing consultation. Approach the questions with openness and curiosity – without expecting to find the final answer right away.
          </div>
          <div class="typentest-steps">
            <div class="typentest-step"><span class="typentest-step__num">1</span><span>Recognize triad <small>(Gut &middot; Heart &middot; Head)</small></span></div>
            <div class="typentest-step"><span class="typentest-step__num">2</span><span>Type within the triad</span></div>
            <div class="typentest-step"><span class="typentest-step__num">3</span><span>Instinctual focus</span></div>
          </div>
          ${bookTip("der-code-deiner-persoenlichkeit", "How the Enneagram type develops &ndash; and what it reveals about our deepest imprints.", "Der Code deiner Persönlichkeit")}
          ${bookTip("die-verborgene-dynamik-der-27-subtypen", "27 Subtypes: Passions, protective strategies, and paths to healing from therapeutic practice.", "Die verborgene Dynamik der 27 Subtypes")}
          <button class="primary" id="tt-start">Start Test →</button>
          <button class="ghost-link" data-route="dashboard">← Back</button>
        </div>
      </div>
    `);
  }

  // Phase 1: Triadenwahl
  if (ts.phase === 1) {
    const triaden = Object.entries(TRIADEN);
    return shell(`
      ${navBar()}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">Step 1 of 3 &middot; Triad</p>
          <h2 class="typentest-titel">Gut, Heart, or Head?</h2>
          <p class="typentest-intro">Read the three blocks carefully. Which one describes you best &ndash; not how you would like to be, but how you <em>really</em> are?</p>
          <div class="typentest-triad-grid">
            ${triaden.map(([key, t]) => `
              <button class="typentest-triad-card" data-tt-triad="${key}">
                <div class="typentest-triad-card__label">${t.label}</div>
                <div class="typentest-triad-card__impuls">${t.grundimpuls}</div>
                <ul class="typentest-triad-card__list">
                  ${t.statements.map(s => `<li>${s}</li>`).join("")}
                </ul>
              </button>
            `).join("")}
          </div>
          <button class="ghost-link" id="tt-back-0">← Back</button>
        </div>
      </div>
    `);
  }

  // Phase 2: Typfragen (5 Fragen, eine nach der anderen)
  if (ts.phase === 2) {
    const fragen = TYPFRAGEN[ts.triad];
    const qi = ts.qIndex;
    const frage = fragen[qi];
    const total = fragen.length;
    const pct = Math.round((qi / total) * 100);
    return shell(`
      ${navBar()}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">Step 2 of 3 &middot; Question ${qi + 1} of ${total}</p>
          <div class="typentest-progress"><div class="typentest-progress__bar" style="width:${pct}%"></div></div>
          <h2 class="typentest-frage">${frage.frage}</h2>
          <p class="typentest-intro">Choose the statement that applies most &ndash; not the ideal one, but the most honest one.</p>
          <div class="typentest-antworten">
            ${frage.antworten.map((a, i) => `
              <button class="typentest-antwort" data-tt-antwort="${a.typ}" data-tt-qi="${qi}">
                <span class="typentest-antwort__buchstabe">${["A","B","C"][i]}</span>
                <span class="typentest-antwort__text">${a.text}</span>
              </button>
            `).join("")}
          </div>
          ${qi > 0 ? `<button class="ghost-link" id="tt-back-q">← Previous Question</button>` : `<button class="ghost-link" id="tt-back-1">← Back to Triad Selection</button>`}
        </div>
      </div>
    `);
  }

  // Phase 3: Instinkt
  if (ts.phase === 3) {
    return shell(`
      ${navBar()}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">Step 3 of 3 &middot; Instinct</p>
          <h2 class="typentest-titel">Your Instinctual Subtype Focus</h2>
          <p class="typentest-intro">Every human being carries all three instincts within &ndash; but one dominates. Which description applies most closely to you?</p>
          <div class="typentest-antworten">
            ${INSTINKTE.map(inst => `
              <button class="typentest-antwort" data-tt-instinkt="${inst.code}">
                <span class="typentest-antwort__buchstabe">${inst.code}</span>
                <div>
                  <strong class="typentest-antwort__label">${inst.label}</strong>
                  <span class="typentest-antwort__text">${inst.beschreibung}</span>
                </div>
              </button>
            `).join("")}
          </div>
          <button class="ghost-link" id="tt-back-2">← Back</button>
        </div>
      </div>
    `);
  }

  // Phase 4: Ergebnis
  if (ts.phase === 4) {
    playMilestone("test-abgeschlossen");
    // Typ mit höchstem Score ermitteln
    const scores = ts.scores;
    const topTyp = Object.entries(scores).sort((a, b) => b[1] - a[1])[0]?.[0];
    const typNum = parseInt(topTyp);
    const typColor = TYPE_COLORS[typNum] || "var(--accent)";
    const typName = TYPNAMEN[typNum] || "";
    const typKurz = TYPKURZ[typNum] || "";
    const instCode = ts.instinkt || "";
    const instLabel = INSTINKTE.find(i => i.code === instCode)?.label || "";
    const subtypeCode = `${instCode.toLowerCase()}${typNum}`;
    const hasSubtype = !!subtypeDetails[subtypeCode];

    return shell(`
      ${navBar()}
      <div class="typentest-wrap">
        <div class="typentest-card typentest-card--result">
          <p class="eyebrow">Your Resulting Type</p>
          <div class="typentest-result-badge" style="border-color:${typColor};color:${typColor}">
            Type ${typNum} · ${instCode}
          </div>
          <h2 class="typentest-titel" style="color:${typColor}">${typName}</h2>
          <p class="typentest-subline">${instCode} &ndash; ${instLabel}</p>
          <p class="typentest-result-text">${typKurz}</p>

          <div class="typentest-disclaimer">
            <strong>For context:</strong> This test is based on self-assessment. Since blind spots are part of personality, the result is an <em>orientation hint</em> — not a verdict. Even very self-aware people have difficulty determining their own type with certainty. For a precise assessment, a personal consultation is recommended.
          </div>

          <div class="typentest-cta-group">
            ${hasSubtype ? `<button class="primary" style="background:${typColor};border-color:${typColor}" data-route="subtype/${subtypeCode}">Go to Subtype Profile: ${instCode.toUpperCase()}${typNum} →</button>` : `<button class="primary" style="background:${typColor};border-color:${typColor}" data-route="type/${typNum}">Go to Type ${typNum} in the Compass →</button>`}
            <p class="typentest-berater-label">Request a consultation appointment:</p>
            <a class="typentest-cta-btn" href="mailto:detlefrathmer@t-online.de?subject=Request%20a%20Typing%20Consultation">✉ Request consultation with Detlef Rathmer</a>
            <a class="typentest-cta-btn typentest-cta-btn--wa" href="https://wa.me/4915758786201?text=I%20would%20like%20to%20request%20a%20typing%20consultation." target="_blank" rel="noopener">WhatsApp Detlef Rathmer</a>
            <a class="typentest-cta-btn" href="mailto:rathmer.david.business@gmail.com?subject=Request%20a%20Typing%20Consultation">✉ Request consultation with David L. Rathmer</a>
            <a class="typentest-cta-btn typentest-cta-btn--wa" href="https://wa.me/4915901902479?text=I%20would%20like%20to%20request%20a%20typing%20consultation." target="_blank" rel="noopener">WhatsApp David L. Rathmer</a>
          </div>

          <button class="ghost-link" id="tt-restart">Retake Test</button>
          <button class="ghost-link" id="tt-merken" data-tt-code="${subtypeCode}">✦ Save My Type</button>
          <button class="ghost-link" data-route="dashboard">← Back to Dashboard</button>
        </div>
      </div>
    `);
  }

  return shell(`${navBar()}<div class="typentest-wrap"><p>Error in the test.</p></div>`);
}

function bindTypentest() {
  const ts = testState;

  // Start
  document.getElementById("tt-start")?.addEventListener("click", () => {
    testState = { phase: 1, triad: null, scores: {}, instinkt: null, qIndex: 0 };
    render();
  });

  // Restart
  document.getElementById("tt-restart")?.addEventListener("click", () => {
    testState = { phase: 0, triad: null, scores: {}, instinkt: null, qIndex: 0 };
    render();
  });

  // Typ merken
  document.getElementById("tt-merken")?.addEventListener("click", () => {
    const btn = document.getElementById("tt-merken");
    const code = btn.dataset.ttCode;
    localStorage.setItem("enneagramm-kompass:profile", code);
    localStorage.setItem("enneagramm-kompass:visited", "1");
    btn.textContent = "\u2713 Gespeichert – auf dem Dashboard immer erreichbar";
    btn.disabled = true;
  });

  // Triaden-Auswahl
  document.querySelectorAll("[data-tt-triad]").forEach(btn => {
    btn.addEventListener("click", () => {
      testState.triad = btn.dataset.ttTriad;
      testState.phase = 2;
      testState.qIndex = 0;
      testState.scores = {};
      history.pushState({test:true}, "");
      render();
    });
  });

  // Antworten Phase 2
  document.querySelectorAll("[data-tt-antwort]").forEach(btn => {
    btn.addEventListener("click", () => {
      const typ = parseInt(btn.dataset.ttAntwort);
      testState.scores[typ] = (testState.scores[typ] || 0) + 1;
      const total = TYPFRAGEN[testState.triad].length;
      if (testState.qIndex < total - 1) {
        testState.qIndex++;
        history.pushState({test:true}, "");
        render();
      } else {
        testState.phase = 3;
        history.pushState({test:true}, "");
        render();
      }
    });
  });

  // Instinkt-Auswahl
  document.querySelectorAll("[data-tt-instinkt]").forEach(btn => {
    btn.addEventListener("click", () => {
      testState.instinkt = btn.dataset.ttInstinkt;
      testState.phase = 4;
      history.pushState({test:true}, "");
      render();
    });
  });

  // Back-Navigation
  document.getElementById("tt-back-0")?.addEventListener("click", () => { testState.phase = 0; render(); });
  document.getElementById("tt-back-1")?.addEventListener("click", () => { testState.phase = 1; testState.qIndex = 0; render(); });
  document.getElementById("tt-back-2")?.addEventListener("click", () => { testState.phase = 2; testState.qIndex = TYPFRAGEN[testState.triad].length - 1; render(); });
  document.getElementById("tt-back-q")?.addEventListener("click", () => { if (testState.qIndex > 0) { testState.qIndex--; render(); } });
}

function _saveMotivState() {
  try { localStorage.setItem("kompass:motivState", JSON.stringify(motivState)); } catch(e) {}
}

function bindMotivtest() {
  // Intro → Start
  document.querySelector("[data-motiv-start]")?.addEventListener("click", () => {
    motivState = { phase: "test", qIndex: 0, answers: {} };
    _saveMotivState();
    history.pushState({test:true}, "");
    render();
  });

  // Next / Ergebnis
  document.querySelector("[data-motiv-next]")?.addEventListener("click", () => {
    if (motivState.qIndex < MOTIVTEST.length - 1) {
      motivState.qIndex++;
    } else {
      motivState.phase = "result";
    }
    _saveMotivState();
    history.pushState({test:true}, "");
    render();
  });

  // Back
  document.querySelector("[data-motiv-back]")?.addEventListener("click", () => {
    if (motivState.qIndex > 0) { motivState.qIndex--; render(); }
  });

  // Überspringen
  document.querySelector("[data-motiv-skip]")?.addEventListener("click", () => {
    if (motivState.qIndex < MOTIVTEST.length - 1) {
      motivState.qIndex++;
    } else {
      motivState.phase = "result";
    }
    render();
  });

  // Antwort auswählen
  document.querySelectorAll("[data-motiv-answer]").forEach(btn => {
    btn.addEventListener("click", () => {
      const letter = btn.dataset.motivAnswer;
      const nr = parseInt(btn.dataset.motivQnr);
      const cur = motivState.answers[nr] || { first: null, second: null };
      if (cur.first === letter) {
        // Deselect first → second becomes first
        motivState.answers[nr] = { first: cur.second, second: null };
      } else if (cur.second === letter) {
        // Deselect second
        motivState.answers[nr] = { first: cur.first, second: null };
      } else if (!cur.first) {
        motivState.answers[nr] = { first: letter, second: cur.second };
      } else if (!cur.second) {
        motivState.answers[nr] = { first: cur.first, second: letter };
      } else {
        // Both taken → replace second
        motivState.answers[nr] = { first: cur.first, second: letter };
      }
      _saveMotivState();
      render();
    });
  });

  // Reset
  document.querySelector("[data-motiv-reset]")?.addEventListener("click", () => {
    motivState = { phase: "intro", qIndex: 0, answers: {} };
    localStorage.removeItem("kompass:motivState");
    render();
  });
}

