function tierlexikonDetailPage(codeRaw) {
  const code = codeRaw.toUpperCase();
  const data = TIERLEXIKON[code];
  if (!data) {
    return shell(`
      ${pageHeader("tierlexikon")}
      <div style="max-width:680px;margin:0 auto;padding:2rem 1rem;">
        <button class="ghost-link" data-route="tierlexikon">&larr; Animal Lexicon</button>
        <p style="margin-top:2rem;color:var(--muted);">${code}: Facts will be added soon.</p>
      </div>
    `);
  }
  const col = typeColorFromCode(code);
  const faktenHtml = data.fakten.map((fakt, i) => {
    const starIdx = fakt.lastIndexOf(" *");
    let haupttext = fakt, kommentar = "";
    if (starIdx !== -1 && fakt.endsWith("*")) {
      haupttext = fakt.slice(0, starIdx).trim();
      kommentar = fakt.slice(starIdx + 2, -1).trim();
    }
    return `
      <div style="
        display:grid;grid-template-columns:2rem 1fr;gap:.5rem;
        padding:.85rem .8rem;
        border-radius:10px;
        background:${i % 2 === 0 ? "var(--paper)" : "transparent"};
        border:1px solid ${i % 2 === 0 ? "var(--line)" : "transparent"};
        margin-bottom:.4rem;
      ">
        <span style="
          font-size:.75rem;font-weight:800;color:${col};
          padding-top:.1rem;text-align:right;opacity:.7;
        ">${i + 1}</span>
        <div>
          <p style="margin:0 0 .35rem;font-size:.88rem;line-height:1.55;color:var(--ink);">${haupttext}</p>
          ${kommentar ? `<p style="margin:0;font-size:.8rem;line-height:1.5;color:${col};font-style:italic;border-left:2px solid ${col};padding-left:.6rem;">${kommentar}</p>` : ""}
        </div>
      </div>
    `;
  }).join("");

  return shell(`
    ${pageHeader("tierlexikon")}
    <div style="max-width:680px;margin:0 auto;padding:0 1rem 3rem;">
      <button class="ghost-link" data-route="tierlexikon">&larr; Animal Lexicon</button>
      <div style="
        display:flex;align-items:center;gap:1.2rem;
        margin:1.4rem 0 .6rem;
      ">
        <div style="position:relative;width:100px;height:100px;border-radius:50%;overflow:hidden;flex-shrink:0;box-shadow:0 0 0 3px ${col};">
          <img
            src="${CDN}assets/${code.toLowerCase()}-tier.jpg"
            alt="${data.tier}"
            style="position:absolute;top:${tierAvatarTop(code)};left:${tierAvatarLeft(code)};width:140%;height:140%;object-fit:cover;"
          />
        </div>
        <div>
          <p class="eyebrow" style="color:${col};margin-bottom:.2rem;">Knowledge &middot; Animal Lexicon</p>
          <h1 style="margin:0 0 .1rem;font-size:1.6rem;color:var(--ink);">${data.tier}</h1>
          ${data.lateinisch ? `<p style="margin:0 0 .15rem;font-size:.82rem;color:var(--muted);font-style:italic;">${data.lateinisch}</p>` : ""}
          <p style="margin:0 0 .4rem;font-size:.78rem;color:var(--muted);opacity:.7;">${code} &middot; ${data.fakten.length} facts</p>
          <button class="ghost-link" data-tier-laut="${data.tier}"
                  style="font-size:.82rem;padding:.25rem .6rem;border:1px solid var(--line);border-radius:20px;opacity:.8;">
            🔊 ${data.tier} call
          </button>
        </div>
      </div>
      <p style="font-size:.88rem;line-height:1.6;color:var(--muted);margin:0 0 1.8rem;padding:.8rem;background:var(--paper);border-radius:10px;border:1px solid var(--line);">${data.intro}</p>
      <div>${faktenHtml}</div>
      ${(() => {
        const d = TIER_DOKU[code];
        if (!d) return "";
        const src = `https://www.youtube.com/embed/${d.ytId}?start=${d.start}&rel=0&modestbranding=1`;
        return `
          <div style="margin-top:2.5rem;">
            <h2 style="font-size:1rem;font-weight:700;color:var(--ink);margin:0 0 .8rem;display:flex;align-items:center;gap:.4rem;">
              🎬 <span>Animal Documentary</span>
            </h2>
            <div style="position:relative;width:100%;padding-top:56.25%;border-radius:12px;overflow:hidden;border:1px solid var(--line);">
              <iframe
                src="${src}"
                title="${d.titel}"
                style="position:absolute;inset:0;width:100%;height:100%;border:none;"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowfullscreen
                loading="lazy"
              ></iframe>
            </div>
            <p style="margin:.5rem 0 0;font-size:.75rem;color:var(--muted);text-align:right;">${d.titel} &middot; ${d.kanal}</p>
            <p style="margin:.4rem 0 0;font-size:.72rem;color:var(--muted);font-style:italic;">🇩🇪 German narration &ndash; enable auto-translated English subtitles via YouTube's settings (⚙).</p>
            <button onclick="window.scrollTo({top:0,behavior:'smooth'})"
                    style="display:block;margin:1.2rem auto 0;background:none;border:1px solid var(--line);border-radius:20px;padding:.35rem 1rem;font-size:.78rem;color:var(--muted);cursor:pointer;">
              ↑ Back to top
            </button>
          </div>
        `;
      })()}
      ${(() => {
        const matches = ANIMAL_RESEARCHER_MATCHES.filter(m => m.subtyp.slice(0, 3) === code);
        if (!matches.length) return "";
        const items = matches.map(m =>
          `<button class="related-link-btn" data-route="${m.route}" style="background:none;border:1px solid var(--gold);color:var(--copper);border-radius:20px;padding:.35rem .95rem;font-size:0.82rem;font-family:'EB Garamond',serif;cursor:pointer;white-space:nowrap;">${m.name} (${m.subtyp}) →</button>`
        ).join("");
        return `
          <div style="margin-top:2rem;padding-top:1.2rem;border-top:1px solid var(--line);">
            <h2 style="font-size:1rem;font-weight:700;margin:0 0 .6rem;color:var(--ink);">✦ Living Proof: ${data.tier} Correspondence</h2>
            <p style="font-size:.85rem;color:var(--muted);margin:0 0 .8rem;">These people devote their life's theme to exactly the ${data.tier} &ndash; and are themselves ${code}.</p>
            <div style="display:flex;flex-wrap:wrap;gap:.5rem;">${items}</div>
          </div>
        `;
      })()}
      ${bookTip("enneagramm-zoo", "27 Animal Portraits – each Subtype animal with character, biology and Enneagram connection.", "Enneagramm-Zoo")}
      ${bookTip("archetypen-der-tiere-im-enneagramm", "The archetypal animals of the 9 types as an inner map – images that work instantly.", "Archetypen der Tiere im Enneagramm")}
      ${relatedLinks([
        {route:"tierlexikon", label:"Back to Animal Lexicon"},
        {route:"tierforscher-uebereinstimmung", label:"Animal-Researcher Correspondence: all 27 subtypes"},
      ])}
    </div>
  `);
}

function obstsortPage() {
  return shell(`
    ${pageHeader("obstsorten")}
    <div style="max-width:680px;margin:0 auto;padding:0 1rem 3rem;">
      <p class="eyebrow">Charts &middot; Archetypes</p>
      <h1 class="section-title">Die 9 Obstsorten</h1>
      <p class="psycho-intro">An enneagrammatic-archetypal consideration: what every fruit reveals about the core essence of a type.</p>
      <img
        src="../assets/obstsorten.jpg"
        alt="Die 9 Obstsorten &ndash; Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;"
      />
      <div class="vb-section" style="max-width:100%;">

        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Type 1 &ndash; The Apple: Perfection as a Principle</h2>
        <p class="vb-intro">The apple is culturally and historically the most significant fruit of all &ndash; a symbol of knowledge, perfection, and moral order. In Western tradition, it stands for the striving for the good as well as the temptation to fail it. Its uniform, symmetrical form, smooth skin, and clear color embody an ideal of aesthetic perfection. It follows a clear logic that the saying "An apple a day keeps the doctor away" refers to discipline and precaution &ndash; both core Type 1 qualities. The apple must be flawless, otherwise it is considered spoiled. Exactly how Type 1 experiences themselves.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Type 2 &ndash; The Strawberry: Sweetness as a Gift</h2>
        <p class="vb-intro">The strawberry gives of itself &ndash; it is soft, fragrant, sweet, and glows in a warm red that inevitably recalls warmth and affection. It grows close to the ground, approachable, seeks the light, and opens up completely. Nobody eats a strawberry without a smile. It brings joy to others without demanding anything &ndash; and spoils quickly if it is not seen. The strawberry nourishes, warms, and touches: the principle of Type 2 in its purest plant form.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Type 3 &ndash; The Grape: Success in Community</h2>
        <p class="vb-intro">Grapes never grow individually &ndash; they emerge in clusters, in large, magnificent groups that signal abundance and overflow. They are the fruit of wine, society, reputation, and celebration. In antiquity, grapes were a symbol of prosperity, fertility, and worldly success. The grapevine needs care, guidance, the right soil &ndash; and then yields a harvest that delights and impresses others. Type 3 in its archetypal quality: productive, presentable, socially effective.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Type 4 &ndash; The Fig: Depth Beneath the Surface</h2>
        <p class="vb-intro">The fig is exotic, mysterious, and paradoxical: unassuming on the outside, breathtakingly beautiful on the inside &ndash; a deep purple traversed by delicate structures. It ripens slowly, demands patience, and is rarely understood. In many cultures, it stands for wisdom, transience, and spiritual depth. The fig is not a fruit for the masses &ndash; it is appreciated by those who are willing to look closer. That is the life feeling of Type 4: I am not to be understood at first sight &ndash; but whoever truly sees me discovers something incomparable.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Type 5 &ndash; The Blueberry: Concentrated Essence</h2>
        <p class="vb-intro">The blueberry is small, unassuming, and reserved &ndash; but within it lies an extraordinary concentration of nutrients, antioxidants, and active compounds. It grows in the silence of remote forests, far from the hustle and bustle. You have to search for it; you have to know where it can be found. Whoever finds it recognizes its hidden wealth. The blueberry does not divide itself up &ndash; it is compact, self-sufficient, self-contained. A striking image for Type 5: small on the outside, immeasurably rich on the inside.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Type 6 &ndash; The Banana: Reliability as a Virtue</h2>
        <p class="vb-intro">The banana is the staple food among fruits &ndash; globally distributed, universally familiar, nourishing, and reliable. It always comes in its protective yellow skin, well-portioned, easy to handle. It provides quick energy in moments of exhaustion and is firm and predictable in its structure. No other fruit conveys such a strong sense of reliability and security. The banana is always there &ndash; and that is precisely the deepest need and simultaneously the greatest gift of Type 6.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Type 7 &ndash; The Pineapple: Exoticism and Joy of Life</h2>
        <p class="vb-intro">The pineapple is a feast for the senses &ndash; exotic, colorful, sweet-tart, surprising, and unconventional in its outer form. It comes from afar, brings the promise of adventure and summerness, and spreads instant high spirits. It is tropical, free, unbound &ndash; and its prickly outer shell protects a tender, glowing core. Just like Type 7: a party on the outside, more sensitive on the inside than they show, and always searching for the next pleasure.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Type 8 &ndash; The Pomegranate: Power and Abundance</h2>
        <p class="vb-intro">The pomegranate is one of the oldest and most mythically charged fruits in human history &ndash; in many cultures a symbol of power, fertility, death, and rebirth all at once. Its hard, resistant skin protects a core of overwhelming abundance: hundreds of glowing red seeds, plump and powerful. You have to exert force to get to it &ndash; but whoever does is richly rewarded. The pomegranate does not give itself away easily; it must be conquered. That is the principle of Type 8: robust on the outside, of astonishing inner abundance &ndash; for those who have the courage to come closer.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Type 9 &ndash; The Peach: Gentleness and Peace</h2>
        <p class="vb-intro">The peach is the most peaceful of all fruits &ndash; soft, warm, velvety, in delicate colors ranging from cream to gold to rosé. It is round and completely self-contained, without sharp corners or edges. Its fragrance is quiet and deep, its taste harmonious without extremes. In Chinese tradition, the peach is considered a symbol of immortality, peace, and cosmic harmony. It does not push itself forward &ndash; it is simply there, quiet and nourishing. The principle of Type 9 in its most beautiful condensation: peace that arises from within itself.</p>

        ${bookTip("wer-du-wirklich-bist-band-1", "Overviews, charts, and type descriptions &ndash; the first volume of the trilogy that brings the Enneagram to life.", "Wer du wirklich bist &ndash; Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Deepened type profiles and archetypal considerations &ndash; Volume 2 of the Rathmer trilogy.", "Wer du wirklich bist &ndash; Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypes, paths of healing, and the big picture &ndash; Volume 3 concluding the trilogy.", "Wer du wirklich bist &ndash; Band 3")}
      </div>
      ${relatedLinks([
        {route:"tierentsprechungen", label:"Animal Equivalents"},
        {route:"tee-enneagramm", label:"Enneagram Teas"},
        {route:"symmetrie-des-enneagramms", label:"Symmetry of the Enneagram"},
      ])}
    </div>
  `);
}

function gemuesesortenPage() {
  return shell(`
    ${pageHeader("gemuesesorten")}
    <div style="max-width:680px;margin:0 auto;padding:0 1rem 3rem;">
      <p class="eyebrow">Charts &middot; Archetypes</p>
      <h1 class="section-title">The 9 Vegetable Varieties</h1>
      <p class="psycho-intro">An enneagrammatic-archetypal consideration: what each vegetable reveals about the core essence of a type.</p>
      <img
        src="../assets/gemuesesorten.jpg"
        alt="Die 9 Gem\xfcse &ndash; Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;"
      />
      <div class="vb-section" style="max-width:100%;">

        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Type 1 &ndash; The Carrot: Clarity as a Principle</h2>
        <p class="vb-intro">The carrot grows straight, clearly structured, always in the same direction &ndash; downward into the depths. It tolerates no curves when the soil is right. Its bright orange color is unmistakable, its interior dense and nutrient-rich. For centuries, the carrot has stood for health, responsibility, and reliability &ndash; the vegetable of reason. It must be clean, neatly washed, undamaged. A bent carrot looks almost like an error in nature. Exactly how Type 1 experiences the world: Straight, clear, and right &ndash; or something is wrong.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Type 2 &ndash; The Pumpkin: Warmth as a Gift</h2>
        <p class="vb-intro">The pumpkin is the most nourishing, warmest vegetable &ndash; it fills soups, comforts in dark seasons, giving itself completely. Its interior is rich, golden, soft. It demands much care while growing &ndash; but it gives back far more than it takes in. In many cultures, the pumpkin stands for generosity, hospitality, and motherhood. It is round, inviting, carrying everything within itself. The principle of Type 2: nourishing from one's own abundance &ndash; and thereby sometimes forgetting to feel one's own emptiness.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Type 3 &ndash; The Bell Pepper: Impact Through Presence</h2>
        <p class="vb-intro">The bell pepper catches the eye even before you have decided what you want &ndash; bright red, orange, yellow, green: it is the vegetable of impact. Colorful, attractive, unmistakable. Raw, grilled, stuffed, or as a sauce &ndash; it excels in every role and always makes a fine appearance. The bell pepper is not the quiet ingredient in the background &ndash; it is the star performer that enhances every plate and is at home in every kitchen worldwide. Type 3 in its archetypal quality: present, impact-conscious, adaptable &ndash; and always where something is created that impresses others.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Type 4 &ndash; The Eggplant: Depth Behind the Color</h2>
        <p class="vb-intro">The eggplant is the most unique vegetable &ndash; a deep, rich violet that no other plant carries in this form. It is unmistakable, almost artistic in appearance. Its interior is complex: raw, it is bitter; it requires transformation to unfold its true depth. It is not a fast vegetable &ndash; it demands patience, a delicate touch, and understanding. Whoever gives it that is rewarded with a multi-layered complexity that other vegetables do not know. The life feeling of Type 4: I am not accessible to everyone &ndash; but for those who understand me, I am incomparable.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Type 5 &ndash; Garlic: Deep Impact in Secrecy</h2>
        <p class="vb-intro">Garlic grows underground, invisible, self-contained, and possessing a virtually overwhelming inner complexity. A single clove &ndash; small, unassuming &ndash; unfolds an impact that changes an entire dish. Garlic has healing properties known for millennia, often underestimated. It does not reveal itself easily; one must first unlock it, whereupon its full power steps forth. It works most strongly in silence. That is the principle of Type 5: compact, self-sufficient, deep &ndash; whoever underestimates it has not yet experienced its strength.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Type 6 &ndash; The Potato: Reliability as a Foundation</h2>
        <p class="vb-intro">The potato is the foundation of European cuisine &ndash; feeding entire continents for centuries. It grows underground, down-to-earth and solid, without fuss. It is not a delicacy; it is a foundation. It is versatile, extremely reliable, and stores well. When all other vegetables are scarce, the potato is still there. In many cultures, it stands for security, home, and the feeling of being provided for. The deepest need and greatest gift of Type 6: Being the foundation upon which others can count.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Type 7 &ndash; The Tomato: Joy of Life Without Limits</h2>
        <p class="vb-intro">The tomato is actually a fruit &ndash; yet it calls itself a vegetable because categories care little for it. It is the most joyful, sunny appearance in the vegetable garden: red, yellow, orange, green, round, elongated, small, gigantic &ndash; it exists in an overwhelming variety and brings color and life to every kitchen. It is at home everywhere, loves the light, ripens in warmth, and tastes best when truly in its element. Fresh from the vine, sun-dried, as a sauce, raw in a salad &ndash; it always finds a way to delight. The principle of Type 7: open to everything, welcome everywhere &ndash; and most alive where the sun shines.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Type 8 &ndash; The Chili: Strength Without Compromise</h2>
        <p class="vb-intro">The chili does not do things by halves &ndash; it is intense, direct, and leaves a lasting impression. Even small amounts change everything. It is not for everyone, it issues a challenge &ndash; and whoever encounters it knows it immediately. In many cultures worldwide, the chili is considered a symbol of vibrancy, courage, and untamed energy. It is not mean &ndash; it is powerful. Whoever knows it knows how to handle it; whoever disregards it learns quickly. The principle of Type 8: direct, uncompromising, vibrant &ndash; and possessing a strength that others feel for a long time.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Type 9 &ndash; Broccoli: Harmony as Nature</h2>
        <p class="vb-intro">Broccoli grows in florets &ndash; many small parts that together yield a harmonious whole. It is peaceful, balanced, internally coherent. No floret pushes forward, none stays behind &ndash; together they form a round, complete shape. Broccoli stands for health without fuss, nutritional value without a need for status. It fits in seamlessly: in soups, salads, casseroles &ndash; without playing the main actor, yet without losing its essence. The principle of Type 9: Harmony not as a compromise, but as a natural state &ndash; the silent center that holds everything together.</p>

        ${bookTip("wer-du-wirklich-bist-band-1", "Overviews, charts, and type descriptions &ndash; the first volume of the trilogy that brings the Enneagram to life.", "Wer du wirklich bist &ndash; Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Deepened type profiles and archetypal considerations &ndash; Volume 2 of the Rathmer trilogy.", "Wer du wirklich bist &ndash; Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypes, paths of healing, and the big picture &ndash; Volume 3 concluding the trilogy.", "Wer du wirklich bist &ndash; Band 3")}
      </div>
      ${relatedLinks([
        {route:"obstsorten", label:"Fruit Varieties of the Types"},
        {route:"tee-enneagramm", label:"Enneagram Teas"},
        {route:"tierentsprechungen", label:"Animal Equivalents"},
      ])}
    </div>
  `);
}

function weinsortenPage() {
  return shell(`
    ${pageHeader("weinsorten")}
    <div style="max-width:680px;margin:0 auto;padding:0 1rem 3rem;">
      <p class="eyebrow">Charts &middot; Archetypes</p>
      <h1 class="section-title">Die 9 Weinsorten</h1>
      <p class="psycho-intro">An enneagrammatic-archetypal consideration: what each wine variety reveals about the core essence of a type.</p>
      <img
        src="../assets/weinsorten.jpg"
        alt="Die 9 Weinsorten &ndash; Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;"
      />
      <div class="vb-section" style="max-width:100%;">

        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Type 1 – Chardonnay: Perfection as a Principle</h2>
        <p class="vb-intro">Chardonnay is the noblest, most demanding white wine variety in the world—in Burgundy, it is the benchmark against which all others are measured. It demands the utmost care from the winemaker: in the vineyard, in the aging, in the harvest. Every imprecision shows immediately in the glass. In its best expression, it possesses flawless clarity and timeless elegance—because everything is right and nothing is superfluous. It tolerates no sloppiness. The principle of Type 1: if the foundation is pure and every step is correct, something unadulterated emerges.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Type 2 – Riesling: Warmth and Depth</h2>
        <p class="vb-intro">Riesling gives itself completely—it expresses its origin, its terroir, its entire inner abundance without concealment. Its aroma is inviting, warm, fruit-laden: peach, apricot, honey—an almost sensual generosity. It nourishes, it opens up, it makes no secret of what it carries. At the same time, it possesses a depth that many underestimate. Riesling gives without demanding—but whoever truly looks discovers how much it holds within. The principle of Type 2: giving of oneself from inner abundance—and being deeper than one might suspect.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Type 3 – Cabernet Sauvignon: Success as a Benchmark</h2>
        <p class="vb-intro">Cabernet Sauvignon is the most successful red wine in the world—in Bordeaux, in Napa Valley, in Chile, in Australia: wherever it grows, it sets the standard. It is powerful, structured, prestigious. It is valued by connoisseurs and desired by the masses—a rare combination. It adapts without losing its essence: in every climate it brings out the best in itself while always remaining unmistakable. Cabernet Sauvignon does not need to force attention—it comes on its own. The principle of Type 3: the best in their class are not cheered because they demand it, but because their performance speaks for itself.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Type 4 – Pinot Noir: Depth Behind Delicateness</h2>
        <p class="vb-intro">Pinot Noir is the most enigmatic of all grapes—delicate, demanding, difficult to cultivate, and yet possessing a beauty that no other variety reaches. It needs exactly the right conditions to open up. In its best expression, it unfolds a bouquet of incredible depth: cherries, earth, roses, leather, violets—layer upon layer. No other wine is so complex, so nuanced, so capable of telling a story. And hardly any other wine is so rarely truly perfect. The life-feeling of Type 4: only those willing to look truly closely discover something incomparable.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Type 5 – Sauvignon Blanc: Precision in Seclusion</h2>
        <p class="vb-intro">Sauvignon Blanc is the most analytical of all wines—its aromas are razor-sharp and precise: gooseberry, citrus grass, mint, flint. It makes no vague hints, it is exact. It does not flaunt volume or opulence, but its clarity is striking. In Sancerre or Marlborough, it appears as concentrated essence: little fuss, much substance. It is no flatterer—it is clear, direct, and entirely self-sufficient in its element. The principle of Type 5: what appears reserved on the outside conceals an acuity of mind on the inside that surprises others.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Type 6 – Merlot: Reliability as a Foundation</h2>
        <p class="vb-intro">Merlot is the most reliable of all red wines—gentle, accessible, never aggressive. It has no rough edges, it overwhelms no one. It is there when you need it, it goes with almost everything, and it rarely disappoints. No wine invites togetherness so effortlessly. In Pomerol, in its best expression, it shows a depth and reliability that astonishes. Merlot is no self-promoter—it is the foundation you can rely on. The principle of Type 6: whoever is always there and never lets you down is appreciated more than they often know themselves.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Type 7 – Primitivo: Pure Joie de Vivre</h2>
        <p class="vb-intro">Primitivo from Apulia is the most joyful of all wines—sweet, lush, full of southern warmth and vitality. It comes from the sunlight, tastes of ripe cherries, dark berries, and a hint of spice, and immediately spreads good cheer. It is carefree, it is inviting, it makes no big fuss. No other wine embodies the feeling of summer, sociability, and enjoying the moment so much. Primitivo lives in the here and now—and carries everyone along with it. The principle of Type 7: joy is not a luxury, but an attitude toward life.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Type 8 – Syrah / Shiraz: Strength Without Compromise</h2>
        <p class="vb-intro">Syrah—known as Shiraz in Australia—makes no half-measures. It is deep, dark, peppery, powerful, and leaves an impression not soon forgotten. It claims space in the glass as it does at the table. It is not for everyone, it demands something of you—but whoever encounters it knows it instantly. In the Rhône it is monumental, in Barossa overwhelming. Syrah does not reveal itself gradually—it enters the room. The principle of Type 8: whoever knows and respects this energy experiences a force and vitality that lingers long beyond the glass.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Type 9 – Rosé: Silent Harmony</h2>
        <p class="vb-intro">Rosé is the mediator among wines—it stands between red and white, joining both together and creating something of its own, light, harmonious. It does not push itself forward, it does not overwhelm, it nowhere gives offense. It is the wine for everyone—always fitting, always welcome, never difficult. In Provence, it possesses a quiet elegance: delicate, balanced, a wine of peace. You don't notice it right away—but when it's missing, something is missing. The principle of Type 9: harmony is not an accident, but the most beautiful form of presence—the quiet center that holds everything together.</p>

        ${bookTip("wer-du-wirklich-bist-band-1", "Overviews, charts, and type descriptions – the first volume of the trilogy that brings the Enneagram to life.", "Wer du wirklich bist &ndash; Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Deepened type profiles and archetypal considerations – Volume 2 of the Rathmer Trilogy.", "Wer du wirklich bist &ndash; Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypes, paths of healing, and the big picture – Volume 3 as the conclusion of the trilogy.", "Wer du wirklich bist &ndash; Band 3")}
      </div>
      ${relatedLinks([
        {route:"obstsorten", label:"Fruit Varieties of the Types"},
        {route:"gemuesesorten", label:"Vegetable Varieties of the Types"},
        {route:"tee-enneagramm", label:"Enneagram Teas"},
      ])}
    </div>
  `);
}

function brotsortenPage() {
  return shell(`
    ${pageHeader("brotsorten")}
    <div style="max-width:680px;margin:0 auto;padding:0 1rem 3rem;">
      <p class="eyebrow">Charts &middot; Archetypes</p>
      <h1 class="section-title">Die 9 Brotsorten</h1>
      <p class="psycho-intro">An enneagrammatic-archetypal consideration: what each bread variety reveals about the core essence of a type.</p>
      <img
        src="../assets/brotsorten.jpg"
        alt="Die 9 Brotsorten &ndash; Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;"
      />
      <div class="vb-section" style="max-width:100%;">

        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Type 1 – Whole Grain Bread: Substance Without Compromise</h2>
        <p class="vb-intro">Whole grain bread is the most consistent of all breads—no white flour, no sugar, no shortcuts. It is baked from the whole grain, nutrient-rich, substantial, without unnecessary frills. Its taste is earthy, robust, straightforward—it hides nothing. Whole grain bread does what it promises: it truly nourishes, it truly fills you up, it truly is healthy. No other bread stands so much for truthfulness and consistency. The principle of Type 1: what is true is completely true—and what is not should not claim to be.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Type 2 – Brioche: Sweetness as a Gift</h2>
        <p class="vb-intro">Brioche is the warmest of all breads—soft, rich in butter, lightly sweet, with an inviting warmth that immediately radiates comfort. It is no everyday bread; it is a gift. In France, it is served on special occasions, for celebration, for joy. Brioche gives itself completely—every ingredient, every step serves the well-being of others. It tastes of devotion. Whoever bakes it is saying: I have invested time in you. The principle of Type 2: giving out of the joy of giving—and in doing so, creating a work that touches others.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Type 3 – Ciabatta: Performance Through Lightness</h2>
        <p class="vb-intro">Ciabatta is the most elegant of all breads—airy, crisp, with an open crumb that suggests lightness while simultaneously showing convincing substance. It is versatile: as a sandwich, for dipping, as an appetizer—it plays every role effortlessly and always cuts a good figure. In Italy, it is the bread of modern success—young, contemporary, known worldwide. Ciabatta doesn't need to explain itself. It simply works. The principle of Type 3: performance should look effortless—even when mastery lies behind it.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Type 4 – Sourdough Bread: Depth Through Transformation</h2>
        <p class="vb-intro">Sourdough bread is the most unique of all breads—no two loaves are alike, each one bears the signature of its own creation. It is not driven by industrial yeast, but by a living, wild starter that can be decades old. The acidity gives it character, depth, and an unmistakable note. It needs time, patience, and a fine sense of feel—whoever is in a hurry gets a different bread. Inside, it is of complex beauty: bubbles, layers, flavors upon flavors. The life-feeling of Type 4: I am the result of my own history—and that is unrepeatable.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Type 5 – Pumpernickel: Concentrated Essence</h2>
        <p class="vb-intro">Pumpernickel is the densest, most concentrated of all breads—compact, dark, of an almost mineral-like intensity. It shows little on the outside: no golden-brown crust, no airy crumb, no quick promise. But within it lies a depth of nutrients and flavor that other breads come nowhere near matching. It is baked slowly, often over many hours, at low temperature—quiet processes that bring out the best. It is not for every palate, but for those who understand it, there is hardly an equivalent. The principle of Type 5: whoever looks inward finds more than the surface promises.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Type 6 – Rye Bread: Reliability as a Virtue</h2>
        <p class="vb-intro">Rye bread is the most reliable of all breads—a staple food in Central and Northern Europe for centuries, tested by generations, never out of fashion. It stays fresh for a long time, nourishes sustainably, tastes good every day. No bread is so down-to-earth, so loyal, so little concerned with attracting attention. Rye bread promises nothing it does not keep—and it keeps what it promises. In times of crisis, it was often the only bread that remained. The deepest principle of Type 6: enduring when others disappear—and never disappointing people's trust.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Type 7 – Focaccia: Joie de Vivre with Herbs</h2>
        <p class="vb-intro">Focaccia is the most joyful of all breads—flat, generously topped, fragrant with olive oil, rosemary, sea salt, tomatoes, olives, whatever one happens to feel like. It invites, it shares itself, it spreads Mediterranean joie de vivre. No bread is so effortlessly sociable: you simply tear off a piece, pass it on, enjoy the moment. Focaccia is not for later—it is for now. It playfully combines flavor and lightness without making a big fuss about it. The principle of Type 7: life is an invitation—and the best part about it is accepting it.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Type 8 – Baguette: Directness as Style</h2>
        <p class="vb-intro">Baguette makes no half-measures—hard and crisp on the outside, airy and robust on the inside, without any apology. It is one of the best-known breads in the world, and it knows it. It claims space: length, presence, a crust that cracks loudly when you break it. It does not adapt—everyone else adapts to it. In France, it is not simply bread, it is a declaration of life. You carry it openly under your arm, unhidden, unwrapped. The principle of Type 8: presence needs no explanation—it is simply there.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Type 9 – White Bread: Silent Harmony</h2>
        <p class="vb-intro">White bread is the most peaceful of all breads—soft, mild, without any rough edges, entirely calm within itself. It does not overwhelm, it does not push itself forward, it makes no demands. It goes with any topping, any occasion, any person. In the morning as toast, at noon as a sandwich, in the evening as a side dish—it fits in without losing itself. Its secret lies in its quietness: it is there, it nourishes, it connects—and you only notice how important it was once it is missing. The principle of Type 9: it is not the loudest thing that matters most, but the one in which everyone can find themselves.</p>

        ${bookTip("wer-du-wirklich-bist-band-1", "Overviews, charts, and type descriptions – the first volume of the trilogy that brings the Enneagram to life.", "Wer du wirklich bist &ndash; Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Deepened type profiles and archetypal considerations – Volume 2 of the Rathmer Trilogy.", "Wer du wirklich bist &ndash; Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypes, paths of healing, and the big picture – Volume 3 as the conclusion of the trilogy.", "Wer du wirklich bist &ndash; Band 3")}
      </div>
      ${relatedLinks([
        {route:"obstsorten", label:"Fruit Varieties of the Types"},
        {route:"gemuesesorten", label:"Vegetable Varieties of the Types"},
        {route:"weinsorten", label:"Wine Varieties of the Types"},
      ])}
    </div>
  `);
}

function kaesesortenPage() {
  return shell(`
    ${pageHeader("kaesesorten")}
    <div style="max-width:680px;margin:0 auto;padding:0 1rem 3rem;">
      <p class="eyebrow">Charts &middot; Archetypes</p>
      <h1 class="section-title">The 9 Cheese Varieties</h1>
      <p class="psycho-intro">An enneagrammatic-archetypal consideration: what each cheese variety reveals about the core essence of a type.</p>
      <img
        src="../assets/kaesesorten.jpg"
        alt="Die 9 K\xe4sesorten &ndash; Schaubild"
        style="width:100%;max-width:680px;display:block;margin:0 auto 2rem;border-radius:12px;cursor:zoom-in;"
      />
      <div class="vb-section" style="max-width:100%;">

        <h2 style="font-size:1.05rem;font-weight:700;margin:0 0 1rem;color:#5f5f5f;">Type 1 – Parmesan: Perfection Through Maturation</h2>
        <p class="vb-intro">Parmesan is the most consistent of all cheeses—hard, crystalline, with a piquancy that arises from long maturation. A genuine Parmigiano Reggiano needs at least twelve months, often two years or more. No shortcuts, no compromises. It tolerates no imitation: the name is protected, production is strictly regulated, quality is verifiable. When cut, it reveals structure and depth—granules that gleam from within. The principle of Type 1: true quality does not emerge from haste, but from consistency, time, and the refusal to let errors pass.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#7a2fa8;">Type 2 – Brie: Warmth as an Invitation</h2>
        <p class="vb-intro">Brie is the warmest of all cheeses—soft, creamy, wrapped in a mild, aromatic rind that immediately radiates comfort. It opens up completely at room temperature, surrenders itself, becomes soft and inviting. Brie makes no fuss—it simply is, warm and generous. It goes with everything and everyone, never disturbs, always enriches. In France, it is the symbol of hospitality and relaxed togetherness. The principle of Type 2: opening up, surrendering, welcoming the other—and finding one's own fulfillment within that.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#1fa688;">Type 3 – Cheddar: Success Through Adaptability</h2>
        <p class="vb-intro">Cheddar is the most successful cheese in the world—it is at home in supermarket chains, on burgers, in upscale kitchens, in every climate and every culture. It is adaptable: mild or aged, young or matured, orange or white. It convinces in every role without bending itself out of shape. Its popularity is no fluke, but the result of genuine quality that always adapts to context. It needs no explanation—it is simply everywhere, and for good reason. The principle of Type 3: success is no stroke of luck, but the ability to bring out the best in oneself within any environment.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#3cbf1f;">Type 4 – Roquefort: Depth Through Transformation</h2>
        <p class="vb-intro">Roquefort is the most striking of all cheeses—intense, complex, streaked with mold that makes it unmistakable and, for many, initially unsettling. It is not a cheese for everyone. Whoever understands it experiences a depth and complexity that other cheeses come nowhere near reaching. In the caves of Aveyron, it ripens in darkness and silence—transformation as the prerequisite for its unique character. The life-feeling of Type 4: I am the result of my deepest experiences—and precisely that makes me incomparable.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#124fcc;">Type 5 – Gruyère: Concentrated Depth</h2>
        <p class="vb-intro">Gruyère is the most precise of all cheeses—firm, dense, with a nuanced flavor that fully reveals itself only upon close tasting. It is no showy cheese, no crowd-pleaser. It shows little on the outside, but its interior is of remarkable complexity: nuts, caramel, a hint of spice—layer upon layer. It matures slowly, in silence, in controlled cellars. Whoever eats it hastily barely notices it. Whoever pauses and truly tastes it is surprised. The principle of Type 5: the greatest depth does not reveal itself immediately; it unfolds only for those willing to look truly closely.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#8a5222;">Type 6 – Gouda: Reliability as a Foundation</h2>
        <p class="vb-intro">Gouda is the most reliable of all cheeses—mild, predictable, always good, never disappointing. For centuries, it has been a staple food in the Netherlands and is known worldwide. You know what you're getting, and you get what you expect. As a young cheese, it is gentle and accessible; as a matured cheese, it develops surprising depth—but it never catches you off guard. It suits every occasion, on bread in the morning, on the cheese platter in the evening. The principle of Type 6: whoever is always there, whoever never disappoints, is valued more than those who shine and fail.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#d4a800;">Type 7 – Camembert: Joie de Vivre with Character</h2>
        <p class="vb-intro">Camembert is the most vibrant of all cheeses—aromatic, expressive, with a white rind of mold that conceals a creamy, almost ecstatically fragrant core. At room temperature, it reaches its full potential: it flows, it perfumes the air, it fills the room. Camembert invites, it sets the mood, it is the life of the cheese platter. Originating from Normandy, it belongs to French joie de vivre like no other. It wants to be shared, enjoyed, and celebrated. The principle of Type 7: the beauty of life lies in experiencing it with others—and being fully present while doing so.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#a00802;">Type 8 – Pecorino: Strength Without Detours</h2>
        <p class="vb-intro">Pecorino is the most powerful of all cheeses—made from sheep's milk, intense, salty, with a directness that leaves no questions open. It claims space in the mouth as it does on the plate. It is no cheese that can be overlooked or passed over. Even a single piece transforms the entire dish. In southern Italy and Sardinia, it has for millennia been part of a culture that values strength, directness, and vitality. No frills, no hide-and-seek. The principle of Type 8: whoever has presence does not need to explain it—it is felt immediately.</p>

        <h2 style="font-size:1.05rem;font-weight:700;margin:1.8rem 0 1rem;color:#cc6e00;">Type 9 – Mozzarella: Silent Harmony</h2>
        <p class="vb-intro">Mozzarella is the most peaceful of all cheeses—white, soft, mild, entirely calm within itself. It does not overwhelm, it does not push itself forward, it demands nothing. It goes with almost everything: with tomato, with salad, with pizza, as an appetizer. It fits in without losing its essence. Eaten fresh from the whey, it possesses a quiet beauty: moist, tender, light—an invitation to stillness. No cheese connects as effortlessly as it does. The principle of Type 9: harmony is not weakness, but the deepest form of presence—the quiet center where everyone comes to rest.</p>

        ${bookTip("wer-du-wirklich-bist-band-1", "Overviews, charts, and type descriptions – the first volume of the trilogy that brings the Enneagram to life.", "Wer du wirklich bist &ndash; Band 1")}
        ${bookTip("wer-du-wirklich-bist-band-2", "Deepened type profiles and archetypal considerations – Volume 2 of the Rathmer Trilogy.", "Wer du wirklich bist &ndash; Band 2")}
        ${bookTip("wer-du-wirklich-bist-band-3", "27 Subtypes, paths of healing, and the big picture – Volume 3 as the conclusion of the trilogy.", "Wer du wirklich bist &ndash; Band 3")}
      </div>

      ${relatedLinks([
        {route:"brotsorten", label:"Bread Varieties of the Types"},
        {route:"weinsorten", label:"Wine Varieties of the Types"},
        {route:"obstsorten", label:"Fruit Varieties of the Types"},
      ])}
    </div>
  `);
}

