// Life Pattern Compass (Lebensmusterkompass) – recurring biographical fingerprints per subtype,
// worked out from the internal analysis of all case portraits in this compass
// (Famous Personalities + Criminal Psychology). No external scientific proof,
// but an internal, coherent observation tool – see the note on the overview page.
//
// lebensmusterkompassPortraitsForCode: automatically collects ALL portraits (Famous
// Personalities + Criminal Psychology) with a matching subtype code from the arrays
// BERUEHMT_PORTRAITS/KRIMINAL_PORTRAITS that are maintained anyway. That way the example
// list on the detail pages updates itself automatically with every new portrait, without
// manually maintaining a separate list.
function lebensmusterkompassPortraitsForCode(code) {
  // Automatically pulls from all three portrait registers (Famous Personalities,
  // Criminal Psychology, Illness Portraits) – any new portrait in one of the three
  // areas automatically appears as an example portrait on the matching subtype's
  // Life Pattern Compass page. See CLAUDE.md ("Lebensmusterkompass – Pflichtschritt").
  const all = [...BERUEHMT_PORTRAITS, ...KRIMINAL_PORTRAITS, ...KRANKHEITS_PORTRAITS];
  return all
    .filter(p => (p.subtyp || "").toUpperCase().startsWith(code))
    .map(p => ({ name: p.name, route: p.route }));
}

// Fine-tuning of animal image alignment (zoom-crop circles, e.g. Life Pattern Compass,
// Tritype page, card views): default left offset is -8%. Individual subtypes whose
// animal is positioned differently in the source image can be overridden here without
// affecting the others.
const TIER_AVATAR_LEFT_OVERRIDES = {
  SE1: -14, SX1: -11, SO2: -14, SX2: -12, SE3: -6, SE4: -3, SX4: -7, SO4: -20, SE5: -11,
  SO5: -11, SE6: -12, SX6: -12, SE7: -11, SO7: -11, SX7: -6, SE8: -15, SO8: -11, SE9: -15, SO9: -14, SX9: -13,
};
export function tierAvatarLeft(code) {
  const c = (code || "").toUpperCase();
  const v = TIER_AVATAR_LEFT_OVERRIDES[c];
  return (typeof v === "number" ? v : -8) + "%";
}
// Vertical fine-tuning (default -20%) – only needed for a few exceptions so far.
const TIER_AVATAR_TOP_OVERRIDES = {
  SX6: -26, SE3: -26,
};
export function tierAvatarTop(code) {
  const c = (code || "").toUpperCase();
  const v = TIER_AVATAR_TOP_OVERRIDES[c];
  return (typeof v === "number" ? v : -20) + "%";
}

// ---------------------------------------------------------------------------
// Pattern Radar: cross-cuts the Life Pattern Compass (which filters WITHIN one
// subtype across all portrait categories). The Pattern Radar filters ACROSS
// all 27 subtypes at once – by wing (w1–w9) or by instinctual variant
// (SE/SO/SX). Built purely from the subtyp fields already maintained on the
// four portrait registers (BERUEHMT_, KRIMINAL_, KRANKHEITS_, ASTROLOGIE_
// PORTRAITS) – no manual upkeep needed, updates itself with every new portrait.
function musterradarParseSubtyp(subtyp) {
  const m = (subtyp || "").toUpperCase().match(/^(SE|SO|SX)([1-9])W?([1-9])?$/);
  if (!m) return null;
  return { instinct: m[1], typ: parseInt(m[2], 10), wing: m[3] ? parseInt(m[3], 10) : null };
}

function musterradarAllPortraits() {
  // ASTROLOGIE_PORTRAITS existiert (Stand jetzt) nur im DE-Bundle, nicht im EN-Bundle –
  // defensiv geprüft, damit das Musterradar unabhängig davon funktioniert.
  const astro = typeof ASTROLOGIE_PORTRAITS !== "undefined" ? ASTROLOGIE_PORTRAITS : [];
  return [...BERUEHMT_PORTRAITS, ...KRIMINAL_PORTRAITS, ...KRANKHEITS_PORTRAITS, ...astro];
}

function musterradarSortKey(subtyp) {
  const p = musterradarParseSubtyp(subtyp);
  if (!p) return [99, 9, 9];
  const instOrder = { SE: 0, SO: 1, SX: 2 };
  return [p.typ, instOrder[p.instinct] ?? 9, p.wing ?? 9];
}

// filterType: "wing" (filterValue = 1–9) or "instinct" (filterValue = "SE"|"SO"|"SX")
function musterradarMatches(filterType, filterValue) {
  const all = musterradarAllPortraits();
  const matches = all.filter(p => {
    const parsed = musterradarParseSubtyp(p.subtyp);
    if (!parsed) return false;
    if (filterType === "wing") return parsed.wing === filterValue;
    if (filterType === "instinct") return parsed.instinct === filterValue;
    return false;
  });
  return matches
    .map(p => ({ name: p.name, route: p.route, subtyp: (p.subtyp || "").toUpperCase() }))
    .sort((a, b) => {
      const ka = musterradarSortKey(a.subtyp), kb = musterradarSortKey(b.subtyp);
      return ka[0] - kb[0] || ka[1] - kb[1] || ka[2] - kb[2];
    });
}

