    if (base === "freischalt") {
      if (hasHeilwissen()) { go("start"); return; }
      app.innerHTML = freischaltPage();
      bindEvents();
      requestAnimationFrame(() => requestAnimationFrame(() => { app.style.opacity = "1"; }));
      return;
    }
